svg.script:

function openAboutBlank() {
  // Open een nieuw leeg tabblad
  const newTab = window.open('about:blank', '_blank');

  if (newTab) {
    // Schrijf HTML direct naar het nieuwe tabblad
    newTab.document.write(`
      <!DOCTYPE html>
      <html lang="nl">
      <head>
          <meta charset="UTF-8">
          <title>Nieuwe Pagina vanuit SVG</title>
          <style>
              body { font-family: Arial, sans-serif; text-align: center; padding-top: 50px; background-color: #f0fdf4; color: #166534; }
              h1 { font-size: 28px; }
          </style>
      </head>
      <body>
          <h1>Hallo vanuit about:blank!</h1>
          <p>Deze pagina is dynamisch gegenereerd via JavaScript vanuit een SVG-bestand.</p>
      </body>
      </html>
    `);
    // Sluit de document stream zodat de browser weet dat het laden klaar is
    newTab.document.close();
  } else {
    alert('Pop-up blocker houdt het openen van het tabblad tegen.');
  }
}
